// Execute some task on boot

// First announce we boot, (stop scene)
if (msg.payload === true) {
    global.set('boot', true);
}

// Annonce to stop activity
global.set('stop', true);

// Memory source and destination
const places = ['file', 'default'];
const place = msg.payload === true ? places : [places[1], places[0]];

node.status({text: place[0] + ' to ' + place[1]});

// Memories to manage
const persistent = {
    'auth': { },
    'mqtt': { },
    'room': { },
    'source': { },
    'parent': { },
    'discovery': { },
    'entity': { },
    'block': { }
}

// Copy backup or at least init
for (const key in persistent) {
    let src = global.get(key, place[0]);
    if (typeof src !== 'object') {
        src = persistent[key];
    }
    global.set(key, src, place[1]);
}

// Stop here on backup process
if (msg.payload === false) {

    // Annonce to stop activity
    global.set('stop', false);

    return;
}

// Check initial memories
const room = global.get('room'); //autoupdate
if (typeof room.base !== 'object') {
    room.base = {};
}
if (typeof room.base.home !== 'object') {
    room.base.home = {
        'id': 'home',
        'name': '> Home',
        'outdoor': 0
    };
}
if (typeof room.base.system !== 'object') {
    room.base.system = {
        'id': 'system',
        'name': '> System',
        'outdoor': 0
    };
}

// Reset non persistent memories
const versatile = {
    'auth': {},
    'browser': {},
    'describe': {
        'app': {
            'project': '',
            'title': '',
            'version': '',
            'mdi': '',
            'login': false // auto login 
        },
        'hmi': {
            'id': '',
            'login': '',
            'level': 'visitor',
            'lang': 'en',
            'page': 'ui - page - auth',
            'room': '',
            'time': 0
        },
        'template': {
            'hmi': {
                'id': '',
                'login': '',
                'level': 'visitor',
                'lang': 'en',
                'page': 'ui - page - auth',
                'room': '',
                'time': 0
            },
            'room': {
                'id': '',
                'name': '',
                'outdoor': 0
            },
            'parent': {
                'id': '',
                'name': '',
                'seen': 0
            },
            'source': {
                'title': '',
                'version': '',
                'git': '',
                'mdi': ''
            },
            'discovery': {
                'name': '',
                'group': '',
                'type': '',
                'unit': '',
                'value': 0,
                'options': {}
            },
            'entity': {
                'uid': '',
                'source': '',
                'id': '',
                'name': '',
                'parent': '',
                'value': '',
                'group': '',
                'room': '',
                'element': '',
                'unit': '',
                'seen': 0,
                'enabled': 0,
                'options': { }
            },
        },
        'color': {
            'on': '#008000',
            'off': '#FF0000',
            'median': '#F08000',
            'none': '#808000',
            'theme': '#0094CE',
            'empty': '#CCCCCC'
        },
        'page': {

        }
    },
    'dictionary': {},
    'form': {},
    'user': {}
};
for (const key in versatile) {
    global.set(key, versatile[key]);
}

// Register page and more
node.send([msg, null]);

// Wait registrations
await new Promise(resolve => setTimeout(resolve, 1000));

// Continue boot
return [null, msg];

// Maintenance for memory var

// Annonce to stop activity
global.set('stop', true);

//...

// Announce to resume activity
global.set('stop', false);

return msg;

// Add page definition to memory

if (typeof msg.payload === 'object'
    && typeof msg.payload.flow === 'string' && msg.payload.flow !== ''
    && typeof msg.payload.id === 'string' && msg.payload.id !== ''
    && typeof msg.payload.icon === 'string' && msg.payload.icon !== ''
    && typeof msg.payload.level === 'object'
) {
    let describe = global.get('describe'); // autoupdate
    describe.page[msg.payload.flow] = msg.payload;
}

msg.payload = '';

return msg;

if (typeof msg.payload === 'object'
    && typeof msg.payload.flow === 'string' && msg.payload.flow !== ''
) {
    let dictionary = global.get('dictionary'); // autoupdate

    for (const lang in msg.payload) {
        if (lang === 'flow' || typeof msg.payload[lang] !== 'object') {

            continue;
        }

        if (typeof dictionary[lang] !== 'object') {
            dictionary[lang] = {};
        }
        if (typeof dictionary[lang][msg.payload.flow] !== 'object') {
            dictionary[lang][msg.payload.flow] = {};
        }
        dictionary[lang][msg.payload.flow] = { ...dictionary[lang][msg.payload.flow], ...msg.payload[lang] };
    }
}

msg.payload = '';

return msg;

// Prepare project query
if (typeof msg.payload.activeProject === 'string') {
    return {
        'topic': '',
        'payload': '',
        'filename': '/data/projects/' + msg.payload.activeProject + '/package.json'
    };
}

return;

delete msg.filename;

// Get memories
let describe = global.get('describe'); // autoupdate

if (typeof msg.payload === 'object') {
    describe.app = {
        'project': msg.payload.name,
        'title': msg.payload.description.slice(5),
        'version' : msg.payload.version,
        'icon': 'alpha-d',
        'login': !!describe.app.login
    };
}

// Set a default empty hmi user
msg.hmi = describe.template.hmi;

msg.payload = '';

// Get UI user
msg = await node.linkcall('common - ui - hmi', msg);

// Set notice
msg.notice = msg.dictionary.notice.boot_success || 'Successfully started';
msg = await node.linkcall('common - ui - notice', msg);

// Wait memories
msg = await node.linkcall('common - wait', msg);

// Annonce to resume activity
global.set('stop', false);

return msg;

if (typeof msg.notice === 'string' && msg.notice !== '') {
    let temp = msg.payload;
    msg.payload = msg.notice;

    node.send([null, msg]);

    msg.payload = temp;
}

return [msg, null];

// Get memories
let form = global.get('form'); // autoupdate
let user = global.get('user'); // autoupdate
let admin = global.get('auth.admin') || {}; // read

// Get UI user structure
if (typeof msg.hmi !== 'object') {
    msg.hmi = { ...global.get('describe.template.hmi') }; // clone
}

// Get UI page
if (typeof msg.name === 'string') {
    msg.hmi.name = msg.name;
    delete msg.name;
}
delete msg.tab; //?

// Get UI user
if (typeof msg._client === 'object' && typeof msg._client.socketId === 'string') {
    // Get use lang
    const browser_lang = global.get('browser["' + msg._client.socketId + '"]["lang"]');
    if (typeof browser_lang === 'string') {
        msg.hmi.lang = browser_lang;
    }
    msg.hmi.id = msg._client.socketId;


    /* Bypass auth */
    //*
    if (!!global.get('describe.app.login') && 
        (typeof user[msg.hmi.id] !== 'object' || user[msg.hmi.id]['login'] === '')
    ) {
        user[msg.hmi.id] = { ...admin };
        user[msg.hmi.id]['login'] = 'admin';

        delete user[msg.hmi.id]['pass'];
    }
    //*/

    if (typeof user[msg.hmi.id] === 'object') {
        user[msg.hmi.id]['time'] = Date.now();

        msg.hmi = {...msg.hmi, ...user[msg.hmi.id]};
    }

    if (typeof form[msg.hmi.id] !== 'object') {
        form[msg.hmi.id] = { };
    }
}

// Get lang dictionary
msg.dictionary = { ...(global.get('dictionary.en') || { }), ...(global.get('dictionary["' + msg.hmi.lang + '"]') || { }) };

return msg;

if (typeof msg.login === 'string' && msg.login !== "" && 
    typeof msg.pass === 'string' && msg.pass !== ""
) {
    msg.login = msg.login.toLowerCase();
    const hash = global.get('auth["' + msg.login + '"]["pass"]');
    if (typeof hash === 'string') {
        msg.hash = hash;

        node.send([msg, null]);

        return;
    }
}

node.send([null, msg]);

return;

// Get memories
let user = global.get('user'); // autoupdate

user[msg._client.socketId] = {
    'login': msg.login,
    'level': global.get('auth["' + msg.login + '"]["level"]') || '',
    'lang': global.get('auth["' + msg.login + '"]["lang"]' ) || '',
    'time': Date.now()
};

delete msg.login;
delete msg.pass;
delete msg.match;
delete msg.hash;

msg.payload = true;

return msg;

// Get memories
let user = global.get('user'); // autoupdate

delete user[msg._client.socketId];

delete msg.login;
delete msg.pass;
delete msg.match;
delete msg.hash;

msg.payload = false;

return msg;

// Get memories
let user = global.get('user'); // autoupdate
let form = global.get('form'); // autoupdate

/* Limit to 6 hours */
const limit = Date.now() - ( 6 * 60 * 60 * 1000);

for (const u in user) {
    if (typeof global.get('auth["' + user[u]["login"] + '"]["level"]') !== 'string' 
    || user[u]["time"] < limit 
    || (typeof msg.login === 'string' && msg.login === user[u]["login"])
    ) {
        delete user[u];
        delete form[u];

        msg.payload = u;
        node.send([msg]);
    }
}

msg.payload = 'cleaned';

return msg;

let has_admin = false;

if (typeof msg.payload === 'object') {
    for (const login in msg.payload) {
        if (typeof msg.payload[login]["pass"] === 'string'
            && typeof msg.payload[login]["pass"] === 'string'
            && typeof msg.payload[login]["level"] === 'string'
        ) {
            if (typeof msg.payload[login]["lang"] !== 'string') {
                msg.payload[login]["lang"] = 'fr';
            }
            if (typeof msg.payload[login]["telegram"] !== 'string') {
                msg.payload[login]["telegram"] = '';
            }

            if (msg.payload[login]["level"] === 'admin') {
                has_admin =  true;
            }

            global.set('auth["' + login + '"]',{
                'pass': msg.payload[login]["pass"],
                'level': msg.payload[login]["level"],
                'lang': msg.payload[login]["lang"],
                'telegram': msg.payload[login]["telegram"]
            });
        }
    }
}

if (!has_admin) {

    return msg;
}

return;

// If there are no users, set an default admin account
msg.payload = {
    'admin': {
        'pass': 'admin',
        'level': 'admin',
        'lang': 'fr',
        'telegram': ''
    }
};

return msg;

global.set('auth', msg.payload);

msg.payload = '';

return msg;

msg.payload = global.get('auth');
delete msg.filename;

return msg;

// Get memories
let form = global.get('form'); // autoupdate

const check = msg.check || '-';

if (msg.hmi.level !== ''
    && msg.hmi.name === global.get('describe.page["' + check + '"]["name"]')
    && global.get('describe.page["' + check + '"]["level"]["' + msg.hmi.level + '"]') === true
) {
    msg.class = '';
    msg.enabled = true;

    if (typeof form[msg.hmi.id][check] !== 'object') {
        form[msg.hmi.id][check] = { };
    }

    // Wait
    msg = await node.linkcall('common - wait', msg);
} else {
    msg.topic = '';
    msg.payload = '';
    msg.class = 'remove';
    msg.enabled = false;
    msg.title = '-';
}

delete msg.check;

return msg;

