// Get memories
let user = global.get('user'); // autoupdate
let form = global.get('form'); // autoupdate
let pages = global.get('describe.page'); // read

// Get ui data
msg = await node.linkcall('common - ui - hmi', msg);

if (!['connect', 'lost', 'change'].includes(msg.payload)) {

    return;
}

if (msg.payload === 'lost') {

    delete user[msg.hmi.id];
    delete form[msg.hmi.id];

    return;
}

// On connect, go to auth page
if (msg.payload === 'connect') {
    // Bypass auth
    msg.payload = !!global.get('describe.app.login') ? pages.home.name : pages.auth.name;
    msg.hmi.name = msg.payload;

    node.send([null, null, msg]);
}

// Prepare ui
msg.buttons = [];
msg.payload = {
    'pages': {
        'show': [],
        'hide': []
    }
};

// check user page right
let allowed = false;
let current = pages.auth.name;
for (const page in pages) {
    if (typeof pages[page]['level'][msg.hmi.level] === 'boolean' 
        && pages[page]['level'][msg.hmi.level] === true
        || pages.auth.name === pages[page]['name']
    ) {
        msg.buttons.push({
            'id': pages[page]['name'],
            'icon': 'mdi-' + pages[page]['icon'],
            'title': msg.dictionary[page]['page_title']
        });
        msg.payload.pages.show.push(pages[page]['name']);
    }
    else {
        msg.payload.pages.hide.push(pages[page]['name']);
    }

    if (pages[page]['name'] === msg.hmi.name) {
        msg.page_title = msg.dictionary[page]['page_title'];
        msg.page_lang = msg.hmi.lang;
    }

    if (pages[page]['name'] === msg.hmi.name && pages[page]['level'][msg.hmi.level] === true) {
        current = pages[page]['name'];
        allowed = true;
    }
}

if (allowed === false) {
    msg.payload = pages.auth.name;

    node.send([null, null, msg]);
    //return;
    msg.hmi.name = msg.payload;
}

// Clear UI form
if (msg.hmi.id !== '') {
    form[msg.hmi.id]['ts'] = Date.now();
}

// page process
let newMsg = {
    'topic': '',
    'payload': msg.hmi.name,
    'hmi': msg.hmi,
    'dictionary': msg.dictionary,
    '_client': msg._client
};

// ui menu
msg.version = global.get('describe.app.version') || '0.0.0';
msg.title = msg.page_title + ' - ' + global.get('describe.app.title');
msg.full = global.get('describe.app.project') + ' v' + msg.version;
msg.current = current;

delete msg.dictionary;

node.send([msg, null, null]);

msg = await node.linkcall('common - ui - latency', msg);

return [null, newMsg, null];

// Get memories
let browser = global.get('browser'); // autoupdate
let pages = global.get('describe.page'); // read

if (msg.payload !== '') {
    for (const page in pages) {
        if (pages[page]['name'] === msg.payload) {
            msg.name = msg.payload;

            // Get ui data
            msg = await node.linkcall('common - ui - hmi', msg);

            return msg;
        }
    }
}

let default_browser = {
    'lang': msg.payload,
    'time': Date.now()
}
browser[msg._client.socketId] = default_browser;

let time = Date.now() - 60000;
for (const b in browser) {
    if (browser[b]['time'] < time) {
        delete browser[b];
    }
}

return;

let old_payload = msg.payload;

if (Array.isArray(msg.show) || Array.isArray(msg.hide)) {
    msg.payload = {
        'groups': { }
    }
    if (Array.isArray(msg.show)) {
        msg.payload.groups.show = msg.show;
    }
    if (Array.isArray(msg.hide)) {
        msg.payload.groups.hide = msg.hide;
    }

    node.send([null, msg]);

    if (Array.isArray(msg.show)) {
        // Wait
        //msg = await node.linkcall('common - wait', msg);
    }
}

msg.payload = old_payload;

delete msg.show;
delete msg.hide;

return [msg, null];

if (typeof msg.enabled === 'boolean' && msg.enabled === true) {
    msg.enabled = true;
    msg.class = '';
} else {
    msg.enabled = false;
    msg.class = 'remove';
}

msg.payload = '';

return msg;

// Get ui data
msg = await node.linkcall('common - ui - hmi', msg);

return msg;

delete msg.filename;

msg.buffersize = msg.payload.length;
msg.headers = {
    'Content-Type':'image/png',
    'Content-Length': msg.buffersize,
    'Connection': 'close'
}

return msg;

const rnd = global.get('random') || '--';
if (typeof rnd !== 'number' || 
    typeof msg.req.params.rnd !== 'string' || 
    rnd !== Number(msg.req.params.rnd)
) {

    node.send([null, msg]);
}

msg.payload = JSON.stringify({
    'auth': global.get('auth'),
    'mqtt': global.get('mqtt')
}, null, 4);

msg.headers = {
    'Content-Type':'application/json',
    'Content-Disposition':'attachment; filename="dknr-backup.json"',
    'Content-Length': msg.payload.length,
    'Connection':'close'	
};

node.send([msg, null]);

return;

if (typeof msg.req.params.room !== 'string') {

    return [ null, msg ];
}

msg.payload = global.get('rooms.map["' + msg.req.params.room + '"]') || '';

if (msg.payload.length === 0) {

    return [ null, msg ];
}

return  [ msg, null ];

// Get http reponse for app map

msg.statusCode = 200;
msg.headers = {
    'Content-Type': 'image/png',
    'Content-Length': msg.payload.length,
    'Connection': 'close'
};

return msg;

// Get memories
let mqtt = global.get('mqtt'); // autoupdate
const app = global.get('describe.app'); // read

if (typeof mqtt.enabled === 'boolean' && mqtt.enabled === true) {
    msg.broker = {};

    if (mqtt.host.length > 0
        && mqtt.port > 0
        && mqtt.topic.length > 0
    ) {
        msg.broker = {
            'broker': mqtt.host,
            'port': mqtt.port,
            'clientid': app.project + 'dev' || 'dknr',
            'birth': {
                'topic': mqtt.topic + '/kernel/state',
                'payload': 'online',
                'qos': 0,
                'retain': false
            },
            'close': {
                'topic': mqtt.topic + '/kernel/state',
                'payload': 'offline',
                'qos': 0,
                'retain': false
            },
            'will': {
                'topic': mqtt.topic + '/kernel/state',
                'payload': 'will',
                'qos': 0,
                'retain': false
            },
            'force': true
        };

        if (mqtt.username.length > 0 && mqtt.password.length > 0) {
            msg.broker.username = mqtt.username;
            msg.broker.password = mqtt.password;
        }

        msg.action = 'connect';
        node.status({
            fill: 'green'
        });

        node.send(msg);

        msg.action = 'subscribe';
        msg.topic = mqtt.topic + '/#';
        msg.payload = '';

        node.send(msg);

    } else {
        mqtt.enabled = false;
        node.status({
            fill: 'red'
        });
    }
} else {
    msg.action = 'disconnect';

    node.send(msg);
}

return;

const mqtt = global.get('mqtt');

if (global.get('stop') || !mqtt.enabled) {

    return;
}

let source = global.get('source'); // autoupdate
let parent = global.get('parent'); // autoupdate
let discovery = global.get('discovery'); // autoupdate
let entity = global.get('entity'); // autoupdate
const template = global.get('describe.template'); // read

msg.topic = msg.topic.slice(mqtt.topic.length + 1);
let path = msg.topic.split('/');
let action = path.shift();
msg.uid = path.join('/');

if (action === 'discovery') {
    // discovery source
    if (path.length === 1) {
        if (typeof msg.payload === 'string' && msg.payload === '') {
            // delete source[path[0]];
        }
        else if (typeof msg.payload === 'object') {
            if (typeof source[path[0]] !== 'object') {
                source[path[0]] = { ...template.source };
            }
            for (const k in template.source) {
                if (msg.payload.hasOwnProperty(k)) {
                    source[path[0]][k] = msg.payload[k];
                }
            }
        }
    }
    // discovery parent
    else if (path.length === 2) {
        if (typeof msg.payload === 'string' && msg.payload === '') {
            // delete parent[path[1]];
        }
        else if (typeof msg.payload === 'object' && (msg.payload.name || '') !== '' && typeof parent[path[1]] !== 'object') {
            parent[path[1]] = { ...template.parent, ...{ 'id': path[1], 'name': msg.payload.name.replace('_', ' ') } };
        }
    }
    // discovery entity
    else if (path.length === 3) {
        node.status({
            'fill': 'blue',
            'text': action + ': ' + msg.uid
        });

        if (typeof msg.payload === 'string' && msg.payload === '') {
            // delete discovery[uid];
        }
        else if (typeof msg.payload === 'object') {
            if (typeof discovery[msg.uid] !== 'object') {
                discovery[msg.uid] = { ...template.discovery };
            }
            for (const k in template.discovery) {
                if (msg.payload.hasOwnProperty(k)) {
                    if (typeof msg.payload[k] === 'object') {
                        discovery[msg.uid][k] = { ...msg.payload[k] };
                    }
                    else {
                        discovery[msg.uid][k] = msg.payload[k];
                    }
                }
            }

            // Update entity
            //msg = await node.linkcall('common - entity - merge', msg);
        }
    }
}
else if (action === 'get' && path.length === 3) {

    // update entity
    msg = await node.linkcall('common - entity - merge', msg);

    if (entity[msg.uid]['value'] !== msg.payload) {
